document.addEventListener('DOMContentLoaded', () => {
    const announcer = document.getElementById('announcer');
    let cartCount = 0;

    // Announce messages to screen readers
    function announce(message) {
        announcer.textContent = message;
        // Clear message after a short delay so repeated announcements work
        setTimeout(() => {
            if (announcer.textContent === message) {
                announcer.textContent = '';
            }
        }, 1000);
    }

    // Add to cart functionality
    const addToCartButtons = document.querySelectorAll('.add-to-cart');
    const cartBadge = document.querySelector('.cart-badge');
    const cartButton = document.querySelector('[aria-label^="Cart"]');

    addToCartButtons.forEach(button => {
        button.addEventListener('click', (e) => {
            const productName = e.target.getAttribute('data-product');
            cartCount++;

            // Update visual badge
            cartBadge.textContent = cartCount;

            // Update accessible label for the cart button
            cartButton.setAttribute('aria-label', `Cart, ${cartCount} items`);

            // Announce to screen reader
            announce(`Added ${productName} to cart`);
        });
    });
});

